/**
 * Unit tests for BasicSerializerFactory#findSuppressableContentValue.
 * Since the method is protected, we use a Test subclass to expose it.
 */
public class BasicSerializerFactory_findSuppressableContentValue_TriageGen0Test {

    private TestableBasicSerializerFactory factory;
    private SerializationConfig mockConfig;
    private JavaType mockContentType;
    private BeanDescription mockBeanDesc;

    /**
     * Subclass to expose the protected method for testing.
     */
    private static class TestableBasicSerializerFactory extends BasicSerializerFactory {
        protected TestableBasicSerializerFactory(SerializerFactoryConfig config) {
            super(config);
        }

        @Override
        protected Iterable<com.fasterxml.jackson.databind.JsonSerializer<?>> customSerializers() {
            return null;
        }

        @Override
        public Object findSuppressableContentValue_Exposed(SerializationConfig config,
                                                           JavaType contentType,
                                                           BeanDescription beanDesc) throws JsonMappingException {
            return super.findSuppressableContentValue(config, contentType, beanDesc);
        }
    }

    @Before
    public void setUp() {
        factory = new TestableBasicSerializerFactory(null);
        mockConfig = Mockito.mock(SerializationConfig.class);
        mockContentType = Mockito.mock(JavaType.class);
        mockBeanDesc = Mockito.mock(BeanDescription.class);
    }

    @Test
    public void testFindSuppressableContentValue_ReturnsNullWhenInclusionIsNull() throws JsonMappingException {
        // Arrange
        when(mockBeanDesc.findSerializationInclusionForContent(null)).thenReturn(null);

        // Act
        Object result = factory.findSuppressableContentValue_Exposed(mockConfig, mockContentType, mockBeanDesc);

        // Assert
        assertNull("Result should be null when inclusion is null", result);
    }

    @Test
    public void testFindSuppressableContentValue_ReturnsNonEmptyWhenInclusionIsNonDefault() throws JsonMappingException {
        // Arrange
        // The method contains a specific branch: if (incl == NON_DEFAULT) return NON_EMPTY
        when(mockBeanDesc.findSerializationInclusionForContent(null)).thenReturn(JsonInclude.Include.NON_DEFAULT);

        // Act
        Object result = factory.findSuppressableContentValue_Exposed(mockConfig, mockContentType, mockBeanDesc);

        // Assert
        assertEquals("NON_DEFAULT should be converted to NON_EMPTY", JsonInclude.Include.NON_EMPTY, result);
    }

    @Test
    public void testFindSuppressableContentValue_ReturnsOriginalInclusionForOtherModes() throws JsonMappingException {
        // Arrange
        // Test other modes like ALWAYS or NON_NULL to cover the 'default' branch in switch
        JsonInclude.Include targetInclusion = JsonInclude.Include.NON_NULL;
        when(mockBeanDesc.findSerializationInclusionForContent(null)).thenReturn(targetInclusion);

        // Act
        Object result = factory.findSuppressableContentValue_Exposed(mockConfig, mockContentType, mockBeanDesc);

        // Assert
        assertEquals("Should return the original inclusion if it is not NON_DEFAULT", targetInclusion, result);
    }

    @Test
    public void testFindSuppressableContentValue_ReturnsAlwaysWhenInclusionIsAlways() throws JsonMappingException {
        // Arrange
        when(mockBeanDesc.findSerializationInclusionForContent(null)).thenReturn(JsonInclude.Include.ALWAYS);

        // Act
        Object result = factory.findSuppressableContentValue_Exposed(mockConfig, mockContentType, mockBeanDesc);

        // Assert
        assertEquals(JsonInclude.Include.ALWAYS, result);
    }
}
